def _resolve_user(authorization: str | None) -> str:
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="Требуется заголовок Authorization: [REDACTED] <api-key>")
    raw_key = authorization.split(" ", 1)[1].strip()
    record = _mongo.api_keys.find_by_hash(hash_key(raw_key))
    if not record:
        raise HTTPException(status_code=401, detail="Неизвестный или отозванный API-ключ")
    return record.user_id

def find_by_hash(self, key_hash: str) -> ApiKey | None:
    doc = self.col.find_one({"key_hash": key_hash, "revoked": False})
    if not doc:
        return None
    doc.pop("_id", None)
    return ApiKey.model_validate(doc)

def save(self, user_id: str, session_id: str, memory: WorkingMemory) -> None:
    payload = {
        "messages": [m.model_dump(mode="json") for m in memory.messages],
        "summary": memory.summary,
        "metadata": memory.metadata,
    }
    self._client.setex(
        self._key(user_id, session_id),
        self._ttl,
        json.dumps(payload, default=str),
    )

